module hipfort_hipsparse
  use hipfort_hipsparse_enums
  implicit none

  !>  \ingroup aux_module
  !>   \brief Create a hipSPARSE handle.
  !>
  !>   \details
  !>   \p hipsparseCreate creates the hipSPARSE library context. It must be
  !>   initialized before any other hipSPARSE API function is invoked and must be passed to
  !>   all subsequent library function calls. The handle should be destroyed at the end
  !>   using hipsparseDestroy().
  interface hipsparseCreate
#ifdef USE_CUDA_NAMES
    function hipsparseCreate_(handle) bind(c, name="cusparseCreate")
#else
    function hipsparseCreate_(handle) bind(c, name="hipsparseCreate")
#endif
      use iso_c_binding
      use hipfort_hipsparse_enums
      implicit none
      integer(kind(HIPSPARSE_STATUS_SUCCESS)) :: hipsparseCreate_
      type(c_ptr) :: handle
    end function
  end interface

  !>  \ingroup aux_module
  !>   \brief Destroy a hipSPARSE handle.
  !>
  !>   \details
  !>   \p hipsparseDestroy destroys the hipSPARSE library context and releases all
  !>   resources used by the hipSPARSE library.
  interface hipsparseDestroy
#ifdef USE_CUDA_NAMES
    function hipsparseDestroy_(handle) bind(c, name="cusparseDestroy")
#else
    function hipsparseDestroy_(handle) bind(c, name="hipsparseDestroy")
#endif
      use iso_c_binding
      use hipfort_hipsparse_enums
      implicit none
      integer(kind(HIPSPARSE_STATUS_SUCCESS)) :: hipsparseDestroy_
      type(c_ptr),value :: handle
    end function
  end interface

  !>  \ingroup aux_module
  !>   \brief Return the string representation of a hipSPARSE status's matching backend status enum
  !>   name
  !>
  !>   \details
  !>   \p hipsparseGetErrorName takes a hipSPARSE status as input and first converts it to the
  !>   matching backend
  !>   status (either \p rocsparse_status or \p cusparseStatus_t). It then returns the string
  !>   representation of this status
  !>   enum name. If the status is not recognized, the function returns "Unrecognized status code".
  !>
  !>   For example, \p hipsparseGetErrorName( `HIPSPARSE_STATUS_SUCCESS` ) on a system with a
  !>   rocSPARSE backend will
  !>   return \p rocsparse_status_success. On a system with a cuSPARSE backend this function would
  !>   return
  !>   \p CUSPARSE_STATUS_SUCCESS.
  interface hipsparseGetErrorName
#ifdef USE_CUDA_NAMES
    function hipsparseGetErrorName_(status) bind(c, name="cusparseGetErrorName")
#else
    function hipsparseGetErrorName_(status) bind(c, name="hipsparseGetErrorName")
#endif
      use iso_c_binding
      use hipfort_hipsparse_enums
      implicit none
      type(c_ptr) :: hipsparseGetErrorName_
      integer(kind(HIPSPARSE_STATUS_SUCCESS)),value :: status
    end function
  end interface

  !>  \ingroup aux_module
  !>   \brief Return the hipSPARSE status's matching backend status description as a string
  !>
  !>   \details
  !>   \p hipsparseGetErrorString takes a hipSPARSE status as input and first converts it to the
  !>   matching backend
  !>   status (either \p rocsparse_status or \p cusparseStatus_t). It then returns the string
  !>   description of this status.
  !>   If the status is not recognized, the function returns "Unrecognized status code".
  interface hipsparseGetErrorString
#ifdef USE_CUDA_NAMES
    function hipsparseGetErrorString_(status) bind(c, name="cusparseGetErrorString")
#else
    function hipsparseGetErrorString_(status) bind(c, name="hipsparseGetErrorString")
#endif
      use iso_c_binding
      use hipfort_hipsparse_enums
      implicit none
      type(c_ptr) :: hipsparseGetErrorString_
      integer(kind(HIPSPARSE_STATUS_SUCCESS)),value :: status
    end function
  end interface

  !>  \ingroup aux_module
  !>   \brief Get the hipSPARSE version.
  !>
  !>   \details
  !>   \p hipsparseGetVersion gets the hipSPARSE library version number.
  !>   - patch = version % 100
  !>   - minor = version / 100 % 1000
  !>   - major = version / 100000
  interface hipsparseGetVersion
#ifdef USE_CUDA_NAMES
    function hipsparseGetVersion_(handle,version) bind(c, name="cusparseGetVersion")
#else
    function hipsparseGetVersion_(handle,version) bind(c, name="hipsparseGetVersion")
#endif
      use iso_c_binding
      use hipfort_hipsparse_enums
      implicit none
      integer(kind(HIPSPARSE_STATUS_SUCCESS)) :: hipsparseGetVersion_
      type(c_ptr),value :: handle
      integer(c_int) :: version
    end function
  end interface

  !>  \ingroup aux_module
  !>   \brief Get the hipSPARSE git revision.
  !>
  !>   \details
  !>   \p hipsparseGetGitRevision gets the hipSPARSE library git commit revision (SHA-1).
#ifndef USE_CUDA_NAMES
  interface hipsparseGetGitRevision
    function hipsparseGetGitRevision_(handle,rev) bind(c, name="hipsparseGetGitRevision")
      use iso_c_binding
      use hipfort_hipsparse_enums
      implicit none
      integer(kind(HIPSPARSE_STATUS_SUCCESS)) :: hipsparseGetGitRevision_
      type(c_ptr),value :: handle
      type(c_ptr),value :: rev
    end function
  end interface
#endif

  !>  \ingroup aux_module
  !>   \brief Specify the user-defined HIP stream.
