      integer(c_int),value :: n
      type(c_ptr),value :: descr
      type(c_ptr),value :: A
      integer(c_int),value :: ld
      type(c_ptr),value :: nnzPerColumn
      type(c_ptr),value :: cscVal
      type(c_ptr),value :: cscRowInd
      type(c_ptr),value :: cscColPtr
    end function

