        bind(c, name="cusparseSpruneDense2csrNnz")
#else
    function hipsparseSpruneDense2csrNnz_(handle,m,n,A,lda,threshold,descr,csrRowPtr, &
        nnzTotalDevHostPtr,buffer) &
        bind(c, name="hipsparseSpruneDense2csrNnz")
#endif
      use iso_c_binding
      use hipfort_hipsparse_enums
      implicit none
      integer(kind(HIPSPARSE_STATUS_SUCCESS)) :: hipsparseSpruneDense2csrNnz_
      type(c_ptr),value :: handle
      integer(c_int),value :: m
      integer(c_int),value :: n
      type(c_ptr),value :: A
      integer(c_int),value :: lda
      real(c_float) :: threshold
      type(c_ptr),value :: descr
      type(c_ptr),value :: csrRowPtr
      integer(c_int) :: nnzTotalDevHostPtr
      type(c_ptr),value :: buffer
    end function

